class Pessoa:
    def __init__(self, nome, idade):
        self.nome = nome
        self.idade = idade

    def apresentar(self):
        return f'{self.nome} tem {self.idade} anos'

pessoas = [Pessoa('Ana', 20), Pessoa('Bia', 22), Pessoa('Caio', 18)]
for pessoa in pessoas:
    print(pessoa.apresentar())

class Pessoa:
